import{_ as i,o as e,c as s,a2 as r}from"./chunks/framework.DPTp4bo7.js";const u=JSON.parse('{"title":"优化壤晶模块","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/improving-the-xircon-module"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/improving-the-xircon-module"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/improving-the-xircon-module"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/improving-the-xircon-module"}]]},"headers":[],"relativePath":"zh/improving-the-xircon-module.md","filePath":"zh/page-8uomH9O3s2X12lpR8z1Pf6.md"}'),o={name:"zh/improving-the-xircon-module.md"};function n(t,a,p,l,c,d){return e(),s("div",null,[...a[0]||(a[0]=[r('<div class="logistics-content"><span class="logistics-source-anchor" id="优化壤晶模块" aria-hidden="true"></span><span class="logistics-source-anchor" id="improving-the-adaptive-xircon-module" aria-hidden="true"></span><span class="logistics-source-anchor" id="优化自适应壤晶模块" aria-hidden="true"></span><h1 id="优化壤晶模块" tabindex="-1">优化壤晶模块 <a class="header-anchor" href="#优化壤晶模块" aria-label="Permalink to &quot;优化壤晶模块&quot;">​</a></h1><blockquote><p>源页面 ID：<code>8uomH9O3s2X12lpR8z1Pf6</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=8uomH9O3s2X12lpR8z1Pf6" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>目前主要许愿如下：</p><ul><li><p>抗一切外部扰动</p></li><li><p>在任意壤晶输出下输出所有多余息壤液</p></li><li><p>无损销毁外源污水</p></li><li><p>反应池利用率拉满</p></li></ul><p>最终希望达成尽可能多甚至全部的许愿。</p><p><span id="source-block-Dg7Gvh9Er1uguOHTC90b7d"></span></p><span class="logistics-source-anchor" id="抗一切外部扰动" aria-hidden="true"></span><span class="logistics-source-anchor" id="resisting-all-external-disturbances" aria-hidden="true"></span><span class="logistics-source-anchor" id="introduce-a-water-treatment-unit-to-avoid-self-locking-caused-by-shortage-of-any-input" aria-hidden="true"></span><span class="logistics-source-anchor" id="引入污水处理机避免任何原料不足造成的自锁" aria-hidden="true"></span><h2 id="抗一切外部扰动" tabindex="-1">抗一切外部扰动 <a class="header-anchor" href="#抗一切外部扰动" aria-label="Permalink to &quot;抗一切外部扰动&quot;">​</a></h2><p>当前自适应毛产蓝图式的壤晶模块存在一个问题，在长时间不输入息壤或息壤不足时，会出现自锁无法自动解除。</p><p>当然，通过修改优先级架构的使用，可以规避息壤不足的问题，不过在存在这个现象的情况下，抗外部bug导致的扰动后可以自动修复还是很值得研究。</p><p>自锁核心原理：壤晶废液与污水同时达到50且正在进行壤晶废液反应（息壤液+污水→壤晶废液+惰性）和壤晶反应（壤晶废液+蓝铁粉→壤晶+污水）时发生自锁。</p><p>自动解锁核心原理：流出壤晶废液或污水即可自动解除自锁。当输出频率不足时，会出现自锁-解锁反复出现，导致的无法达成最大速率。</p><p>预防自锁核心原理：（防止两者同时达到50，使其中一个阻塞另一个生产）或（在两者达到50时通过不输入壤晶废液反应的原料息壤液（息壤或水）使壤晶废液反应在此时不发生，发生时不再两者同为50）或（在两者达到50时，确保蓝铁粉不充足，不发生壤晶反应）。</p><p>息壤不足自锁原理：息壤不足，且连续输入壤晶废液，壤晶废液生产污水导致都变成50，但是没有壤晶废液反应，没有自锁；输入息壤消耗1污水开始壤晶废液反应，壤晶反应完成产生1污水使污水变成50,再消耗2壤晶废液开始壤晶反应；连续1s输入2壤晶废液使壤晶废液变成50，此时双50且有壤晶反应和壤晶废液反应，发生自锁。相应的，输入污水则不会自锁。</p><p>壤晶堵满自锁原理：壤晶堵后，壤晶反应堵死，连续输入污水，生产壤晶的反应池依旧正常进行壤晶废液反应，导致两者到达50后自然进入自锁。相应的，输入壤晶废液则不会自锁。</p><p><span id="source-block-lO5YA2Lxodej3ZjTjFqL43"></span></p><span class="logistics-source-anchor" id="污水大回环" aria-hidden="true"></span><span class="logistics-source-anchor" id="a-giant-sewage-loop" aria-hidden="true"></span><h3 id="污水大回环" tabindex="-1">污水大回环！？ <a class="header-anchor" href="#污水大回环" aria-label="Permalink to &quot;污水大回环！？&quot;">​</a></h3><p>让污水保持流动从而永远无法堵满，于是无法触发由壤晶废液和污水均堵满导致的扩容反应池自锁</p><p>与此同时污水的流动需要给壤晶反应提供足够的空位，初步认为流动应当大于等于壤晶反应量</p><p>与其说不自锁不如说时刻能解除自锁</p><p><span class="mark-grey">jnk：显然流动量不足时会偶发自锁导致降速，流量过大会缺少原料导致降速，需要进行一定的流量限制</span></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-85e771d93d2e4072.q90-8f2a595dc6a30541.webp" alt="优化壤晶模块"></p><div class="logistics-image-caption" data-source-block="PEjMXGVRIQXZ0vHZ9QDXmv"><p>深紫色污水|深绿色惰性壤晶废液|青色壤晶废液|绿色息壤液|蓝色水|物流桥 取货口</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-6737f121e4c4bb48.q90-6717b9df1a8ecda9.webp" alt="优化壤晶模块"></p><p><span id="source-block-jBnSJrOPDTQO0BJbdch9mj"></span></p><span class="logistics-source-anchor" id="结构稳定性相关测试结果" aria-hidden="true"></span><h4 id="结构稳定性相关测试结果" tabindex="-1">结构稳定性相关测试结果 <a class="header-anchor" href="#结构稳定性相关测试结果" aria-label="Permalink to &quot;结构稳定性相关测试结果&quot;">​</a></h4><p>暂时缺乏补充</p><p><span id="source-block-zkScXyZKhCJSPKtTVx2DK2"></span></p><span class="logistics-source-anchor" id="部分壤晶输出下输出所有多余息壤液" aria-hidden="true"></span><span class="logistics-source-anchor" id="exporting-all-surplus-liquid-xiranite-over-part-of-the-xircon-output-range" aria-hidden="true"></span><h3 id="部分壤晶输出下输出所有多余息壤液" tabindex="-1">部分壤晶输出下输出所有多余息壤液 <a class="header-anchor" href="#部分壤晶输出下输出所有多余息壤液" aria-label="Permalink to &quot;部分壤晶输出下输出所有多余息壤液&quot;">​</a></h3><p>by kokobird</p><p><strong>终末地千禧年难题之——三扩一反外入息壤液，壤晶堵塞时保持自身90/m的液化息壤生产速度，降低外入息壤液速度。</strong></p><p><strong>或者等价形式：四扩，优先保证壤晶生产，输出所有多余的液化息壤</strong></p><p>这个问题的关键在于设备数很有限，输出口也很有限。如果是三扩二反，会很好做。讨论这个问题你需要：</p><ol><li><p>会计算不同壤晶输出速度下，考虑提纯机时的<strong>液化息壤、壤晶废液生产分配</strong></p></li><li><p>知道壤晶堵塞会如何传播，以及设计路线<strong>让壤晶堵塞传播到外入息壤液</strong>上</p></li><li><p>知道<strong>扩容反应池的各类细节机制</strong>，例如优先输出还是反应，污水废液自锁的条件</p></li><li><p>由于口子很有限，需要混管输入，因此还需要懂<strong>混管的机制和堵塞判断</strong></p></li><li><p>甚至涉及到扩容反应池中反应相位区别，需要会<strong>时序生产分析</strong>。</p></li><li><p>……</p></li></ol><p>下图一种解法，关键是让壤晶废液不要一次进太多，否则会卡污水：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-9e89f67dc425f83f.q90-51069d13fbc5accd.webp" alt="优化壤晶模块"></p><p>以下是ai关于以上产线设计拉的史，有空再回来改</p><p><a href="/endfield-skydoc/zh/research-report-adaptive-xircon-module-and-inlet-recirculation-rate">研究报告-自适应壤晶模块与入口回流限流</a></p></div>',1)])])}const g=i(o,[["render",n]]);export{u as __pageData,g as default};
